/* Toolbox Utilities: offline-first, no financial data transmitted. */
(()=>{'use strict';
const KEY='toolbox-utilities-v1';let data={};try{data=JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{};
const icons={currency:'⇄',contrib:'▤',invoice:'▧',contract:'◷',allot:'◉',weather:'≋',travel:'✈'};
const tools=[['currency','Currency Converter','PHP / USD and custom exchange rates'],['contrib','Contribution Tracker','SSS, PhilHealth, Pag-IBIG and more'],['invoice','Invoice & Receipt','Printable invoice with totals'],['contract','Contract & Shore Leave','Sign-off and shore leave countdowns'],['allot','Allotment Splitter','Salary, family, savings and funds'],['weather','Waves, Wind & Tides','Marine weather links and safety guidance'],['travel','Travel Budgeter','Plan and track trip expenses']];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v)=>Number.isFinite(+v)?+v:0;const money=(v,c='PHP')=>new Intl.NumberFormat('en-PH',{style:'currency',currency:c,maximumFractionDigits:2}).format(n(v));
function save(){try{localStorage.setItem(KEY,JSON.stringify(data))}catch{alert('Storage is full. Please export your data or free device storage.')}}
function field(label,id,type='text',val='',extra=''){return `<label class="utility-field">${esc(label)}<input id="ut-${id}" type="${type}" value="${esc(val)}" ${extra}></label>`}
function choose(label,id,opts,val){return `<label class="utility-field">${label}<select id="ut-${id}">${opts.map(x=>`<option ${x===val?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`}
function button(label,action='save'){return `<button type="button" class="utility-btn" data-utility-action="${action}">${label}</button>`}
function card(title,body){return `<section class="utility-panel"><h3>${title}</h3>${body}</section>`}
function currency(){let d=data.currency||{};return card('Currency Converter',`<p class="utility-note">Default PHP ↔ USD. Enter a rate manually; no live exchange-rate feed is connected.</p><div class="utility-two">${choose('From','from',['USD','PHP','EUR','NOK','SGD','JPY'],d.from||'USD')}${choose('To','to',['PHP','USD','EUR','NOK','SGD','JPY'],d.to||'PHP')}</div>${field('Amount','amount','number',d.amount??100,'min="0" step="any"')}${field('Rate: 1 unit of From equals units of To','rate','number',d.rate??58,'min="0.000001" step="any"')}<div class="utility-two">${button('Swap currencies','swap')}${button('Calculate','save')}</div><div class="utility-result" id="ut-result">${d.result||'Enter the current exchange rate, then calculate.'}</div>`)}
function contrib(){let d=data.contrib||{};return card('Contribution Tracker',`<p class="utility-note">Manual personal tracker. These amounts are not official SSS, PhilHealth, or Pag-IBIG assessments.</p>${choose('Contribution type','type',['SSS','PhilHealth','Pag-IBIG','Other'],d.type||'SSS')}${field('Months expected','expected','number',d.expected??12,'min="0" step="1"')}${field('Months paid','paid','number',d.paid??0,'min="0" step="1"')}${field('Monthly contribution (PHP)','monthly','number',d.monthly??0,'min="0" step="0.01"')}${field('Accumulated onboard earnings (PHP)','earnings','number',d.earnings??0,'min="0" step="0.01"')}${button('Calculate & Save')}<div class="utility-result" id="ut-result">${d.result||'Your contribution summary will appear here.'}</div>`)}
function invoice(){let d=data.invoice||{};return card('Invoice & Receipt Generator',`<p class="utility-note">Creates a printable invoice or receipt. No payment is collected.</p>${choose('Document','kind',['Invoice','Receipt'],d.kind||'Invoice')}${field('Document number','number','text',d.number||'INV-001')}${field('From / issuer','issuer','text',d.issuer||'')}${field('Bill to / recipient','recipient','text',d.recipient||'')}${field('Description','description','text',d.description||'')}${field('Quantity','quantity','number',d.quantity??1,'min="0" step="any"')}${field('Unit price (PHP)','price','number',d.price??0,'min="0" step="any"')}${field('Discount (PHP)','discount','number',d.discount??0,'min="0" step="any"')}${field('Tax (%)','tax','number',d.tax??0,'min="0" step="any"')}${button('Save & Preview','invoice-preview')}<div class="utility-result" id="ut-result">${d.result||'Fill in the invoice details to preview and print.'}</div>`)}
function contract(){let d=data.contract||{};return card('Contract & Shore Leave Countdown',`<p class="utility-note">Estimates only. Confirm dates with your vessel or company.</p>${field('Sign-on date','start','date',d.start||'')}${field('Expected sign-off date','end','date',d.end||'')}${field('Port call / shore leave start','shore','datetime-local',d.shore||'')}${field('Shore leave duration (hours)','hours','number',d.hours??8,'min="0" step="0.5"')}${button('Save & Calculate')}<div class="utility-result" id="ut-result">${d.result||'Add dates to see your countdown.'}</div>`)}
function allot(){let d=data.allot||{};return card('Allotment & Remittance Splitter',`<p class="utility-note">Plan monthly allocations. Your entered exchange rate is used; figures are estimates.</p>${field('Monthly onboard salary (USD)','salary','number',d.salary??0,'min="0" step="any"')}${field('USD to PHP exchange rate','rate','number',d.rate??58,'min="0" step="any"')}${field('Family allotment (PHP)','family','number',d.family??0,'min="0" step="any"')}${field('Savings (PHP)','savings','number',d.savings??0,'min="0" step="any"')}${field('Shore fund (PHP)','shore','number',d.shore??0,'min="0" step="any"')}${field('Debt repayment (PHP)','debt','number',d.debt??0,'min="0" step="any"')}${button('Calculate Split')}<div class="utility-result" id="ut-result">${d.result||'Enter amounts to see your allocation.'}</div><div class="utility-split" id="ut-split"></div>`)}
function weather(){return card('Waves, Wind & Tides',`<p class="utility-note">Live marine forecasts are not integrated into this offline suite. Use an approved onboard source for navigation and operational decisions.</p><div class="utility-links"><a href="https://www.windy.com/" target="_blank" rel="noopener noreferrer">Open Windy weather map ↗</a><a href="https://www.windy.com/-Waves-waves" target="_blank" rel="noopener noreferrer">View wave forecast ↗</a><a href="https://www.tideschart.com/" target="_blank" rel="noopener noreferrer">Look up local tide tables ↗</a></div><p class="utility-note">These links require internet and lead to external providers. Forecasts, tides and port conditions must be verified against official marine information.</p>`)}
function travel(){let d=data.travel||{};return card('Travel Expense Budgeter',`${field('Trip name','trip','text',d.trip||'Next trip')}${field('Total budget (PHP)','budget','number',d.budget??0,'min="0" step="any"')}${field('Flights / transport (PHP)','transport','number',d.transport??0,'min="0" step="any"')}${field('Accommodation (PHP)','hotel','number',d.hotel??0,'min="0" step="any"')}${field('Food (PHP)','food','number',d.food??0,'min="0" step="any"')}${field('Documents / fees (PHP)','fees','number',d.fees??0,'min="0" step="any"')}${field('Other (PHP)','other','number',d.other??0,'min="0" step="any"')}${button('Calculate Budget')}<div class="utility-result" id="ut-result">${d.result||'Your trip budget summary will appear here.'}</div>`)}
const views={currency,contrib,invoice,contract,allot,weather,travel};let current='';
function mount(){const host=document.getElementById('view');if(!host)return;host.innerHTML=`<div class="utility-screen"><button class="utility-back" type="button" data-utility-back>← Home</button><div class="utility-hero"><span>SEAFARER UTILITY SUITE</span><h1 id="utility-title"></h1><p>Practical tools for life at sea and ashore.</p></div><div id="utility-body"></div><p class="utility-disclaimer">Personal entries stay in this browser's local storage. Back them up before clearing app data. Do not enter sensitive financial account numbers.</p></div>`;show(current)}
function show(id){current=id;const t=tools.find(x=>x[0]===id);if(!t)return;document.getElementById('utility-title').textContent=t[1];document.getElementById('utility-body').innerHTML=views[id]();}
function input(id){return document.getElementById('ut-'+id)?.value||''}
function gather(ids){return Object.fromEntries(ids.map(k=>[k,input(k)]))}
function update(){let d={},r='';if(current==='currency'){d=gather(['from','to','amount','rate']);r=`${money(n(d.amount)*n(d.rate),d.to)} · ${n(d.amount)} ${d.from} × ${n(d.rate)} (manual rate)`}
if(current==='contrib'){d=gather(['type','expected','paid','monthly','earnings']);const paid=Math.max(0,n(d.paid)),expected=Math.max(0,n(d.expected)),total=paid*n(d.monthly);r=`${esc(d.type)} · ${paid} months paid · ${Math.max(0,expected-paid)} missed / unrecorded months · Total contributed ${money(total)} · Onboard earnings ${money(d.earnings)} · Earnings less contributions ${money(n(d.earnings)-total)}`}
if(current==='invoice'){d=gather(['kind','number','issuer','recipient','description','quantity','price','discount','tax']);const subtotal=n(d.quantity)*n(d.price),taxable=Math.max(0,subtotal-n(d.discount)),tax=taxable*n(d.tax)/100;d.total=taxable+tax;r=`Subtotal ${money(subtotal)} · Tax ${money(tax)} · Total ${money(d.total)}`}
if(current==='contract'){d=gather(['start','end','shore','hours']);const now=new Date(),start=d.start?new Date(d.start+'T00:00:00'):null,end=d.end?new Date(d.end+'T00:00:00'):null;const day=x=>Math.ceil((x-now)/86400000);let parts=[];if(start&&end&&end>start){let pct=Math.min(100,Math.max(0,Math.round((now-start)/(end-start)*100)));parts.push(`Contract ${pct}% elapsed · ${day(end)>0?day(end)+' days until estimated sign-off':Math.abs(day(end))+' days past estimated sign-off'}`)}if(d.shore){let shore=new Date(d.shore),finish=new Date(shore.getTime()+n(d.hours)*3600000);parts.push(now<shore?`${Math.ceil((shore-now)/60000)} minutes until shore leave`:now<finish?`${Math.ceil((finish-now)/60000)} minutes of shore leave remaining`:'Shore leave period ended')}r=parts.join(' · ')||'Enter valid dates to calculate.'}
if(current==='allot'){d=gather(['salary','rate','family','savings','shore','debt']);const total=n(d.salary)*n(d.rate),allocated=['family','savings','shore','debt'].reduce((s,k)=>s+n(d[k]),0);d.balance=total-allocated;r=`Salary ${money(total)} · Allocated ${money(allocated)} · ${d.balance<0?'Overallocated':'Unallocated'} ${money(Math.abs(d.balance))}`}
if(current==='travel'){d=gather(['trip','budget','transport','hotel','food','fees','other']);const spent=['transport','hotel','food','fees','other'].reduce((s,k)=>s+n(d[k]),0),left=n(d.budget)-spent;r=`${esc(d.trip)} · Planned expenses ${money(spent)} · ${left<0?'Over budget':'Remaining'} ${money(Math.abs(left))}`}
d.result=r;data[current]=d;save();document.getElementById('ut-result').textContent=r;if(current==='allot'){const total=n(d.salary)*n(d.rate);const rows=[['Family',n(d.family)],['Savings',n(d.savings)],['Shore',n(d.shore)],['Debt',n(d.debt)],['Unallocated',Math.max(0,d.balance)]];document.getElementById('ut-split').innerHTML=rows.map(([label,v])=>`<div class="utility-bar-row"><span>${label} · ${money(v)}</span><div><i style="width:${total?Math.min(100,v/total*100):0}%"></i></div></div>`).join('')}}
function printInvoice(){update();const d=data.invoice;if(!d.issuer||!d.recipient){alert('Please enter an issuer and recipient first.');return}const w=window.open('','_blank');if(!w){alert('Allow popups to preview the invoice.');return}const html=`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(d.kind)} ${esc(d.number)}</title><style>body{font:16px system-ui;max-width:750px;margin:35px auto;padding:20px;color:#183e32}h1{border-bottom:4px solid #166448;padding-bottom:15px}section{margin:25px 0}.total{font-size:24px;font-weight:800;text-align:right}.signature{margin-top:90px;border-top:1px solid #999;width:230px}button{background:#166448;color:white;padding:12px;border:0;border-radius:10px}@media print{button{display:none}body{margin:0}}</style></head><body><button onclick="window.print()">Print / Save PDF</button><h1>${esc(d.kind)} · ${esc(d.number)}</h1><section><b>From</b><p>${esc(d.issuer)}</p><b>To</b><p>${esc(d.recipient)}</p></section><section><b>Description</b><p>${esc(d.description)}</p><p>${esc(d.quantity)} × ${money(d.price)}</p><p>Discount ${money(d.discount)} · Tax ${esc(d.tax)}%</p></section><p class="total">Total: ${money(d.total)}</p><div class="signature">Authorized signature</div></body></html>`;w.document.write(html);w.document.close()}
function init(){const old=window.ecosystemAndRating;if(typeof old==='function'){window.ecosystemAndRating=function(){const existing=old();const start=existing.indexOf('<section class="ecosystem-card">'),end=existing.indexOf('</section>',start);const ad=start>=0&&end>=0?existing.slice(0,start)+existing.slice(end+10):existing;return `<section class="utility-feature"><div class="utility-feature-head"><span>SEAFARER UTILITY SUITE</span><h2>Tools for every voyage</h2><p>Swipe or tap a card to open a dedicated tool.</p></div><div class="utility-marquee" aria-label="Seafarer utilities" tabindex="0"><div class="utility-track">${[...tools,...tools].map(([id,title,desc],i)=>`<button type="button" class="utility-tile" data-utility-open="${id}" ${i>=tools.length?'aria-label="Open '+esc(title)+'"':''}><span class="utility-tile-icon" aria-hidden="true">${icons[id]}</span><strong>${esc(title)}</strong><small>${esc(desc)}</small><span class="utility-tile-link">Open tool →</span></button>`).join('')}</div></div></section>`+ad}}}
// This script loads after toolbox2.js has rendered its first screen. Re-render Home to replace the announcement.
init();if(typeof window.render==='function'&&document.querySelector('.home-banner'))window.render();
document.addEventListener('click',e=>{const open=e.target.closest('[data-utility-open]');if(open){e.preventDefault();const id=open.dataset.utilityOpen;if(!views[id])return;const state=window.state;if(state){state.tab='home';state.page='utility-'+id}current=id;mount();window.scrollTo(0,0);return}if(e.target.closest('[data-utility-back]')){if(typeof window.navigate==='function')window.navigate('home');else location.reload();return}const act=e.target.closest('[data-utility-action]');if(!act)return;if(act.dataset.utilityAction==='swap'){const from=document.getElementById('ut-from'),to=document.getElementById('ut-to'),rate=document.getElementById('ut-rate');[from.value,to.value]=[to.value,from.value];if(n(rate.value)>0)rate.value=(1/n(rate.value)).toFixed(6);update();return}if(act.dataset.utilityAction==='invoice-preview'){printInvoice();return}update()});
})();
